SET NOCOUNT ON; SELECT script_name + ' | ' + CONVERT(varchar(19), applied_at, 120) AS v FROM dbo.yj_schema_log WHERE script_name LIKE '%mold-recipe%' ORDER BY applied_at; SELECT CASE WHEN OBJECT_ID('dbo.wo_mixing_head') IS NULL THEN 'wo_mixing_head MISSING' ELSE 'wo_mixing_head OK' END AS o, CASE WHEN COL_LENGTH('dbo.plang','成型配方单号') IS NULL THEN 'plang.成型配方单号 MISSING' ELSE 'OK' END AS p;
